const out=[];
for(const it of $input.all()){
 const r=it.json;
 if(!r||!r.company_domain) continue;
 const now=Number(r.active_users_7d||0), prev=Number(r.active_users_prev_7d||0);
 const wauDrop=prev>0?Math.round(((prev-now)/prev)*100):0;
 const lastLogin=r.last_login_at?new Date(r.last_login_at).getTime():null;
 const daysIdle=lastLogin?Math.floor((Date.now()-lastLogin)/86400000):null;
 const seats=Number(r.seats_purchased||0);
 out.push({json:{
  visitor_anonymous_id:'usage:'+(r.account_id||r.id),
  company_domain:r.company_domain,
  source:'plg_usage',
  signals:{wau_drop_pct:wauDrop,days_since_last_login:daysIdle,seat_utilization_pct:seats>0?Math.round((now/seats)*100):null,key_feature_events_7d:Number(r.key_feature_events_7d||0)}
 }});
}
return out;

const BLOCKED=new Set(['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','proton.me','protonmail.com','aol.com','live.com','msn.com','gmx.com','yandex.com','mail.com','example.com']);
const seen=new Set(); const out=[];
for(const it of $input.all()){
 const b=(it.json&&it.json.body!==undefined&&typeof it.json.body==='object')?it.json.body:it.json;
 const vid=String(b.visitor_anonymous_id??'').trim();
 const raw=String(b.company_domain??'').trim();
 if(!vid||!raw) continue; // drop instantly
 let d=raw.toLowerCase().replace(/^[a-z][a-z0-9+.-]*:\/\//,'').replace(/^[^@\/]*@/,'');
 d=d.split(/[\/?#]/)[0].split(':')[0].replace(/^www\./,'').replace(/\.$/,'');
 if(!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(d)) continue;
 if(BLOCKED.has(d)||seen.has(d)) continue;
 seen.add(d);
 out.push({json:{
  visitor_anonymous_id:vid, company_domain:d,
  source:String(b.source||'inbound_web'),
  page_url:b.page_url||null, utm_source:b.utm_source||null, utm_campaign:b.utm_campaign||null,
  signals:b.signals&&typeof b.signals==='object'?b.signals:{},
  received_at:new Date().toISOString(),
  execution_id:String($execution.id), workflow_id:String($workflow.id), t_start:Date.now()
 }});
}
return out;

const leads=$input.all().map(i=>i.json).filter(l=>l&&/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(String(l.company_domain||'')));
if(!leads.length) return [];
const domains=[...new Set(leads.map(l=>l.company_domain))];
const list=domains.map(d=>'"'+d+'"').join(',');
return [{json:{cache_filter:'company_domain=in.('+list+')',leads}}];

const seen=new Set();
const leads=$('Build Cache Query').all().flatMap(i=>i.json.leads||[]).filter(l=>l&&l.company_domain&&!seen.has(l.company_domain)&&seen.add(l.company_domain));
const rows=$input.all().map(i=>i.json).filter(r=>r&&r.company_domain);
const byDomain=new Map(rows.map(r=>[r.company_domain,r]));
return leads.map(l=>{const r=byDomain.get(l.company_domain);return {json:{...l,cache_hit:!!r,cache_row_id:r?(r.id??r.company_domain):null,cache_status:r?(r.routing_status??r.status??null):null}};});

// ---- EDIT THESE ICP CONSTANTS ----
const MIN_PRESCORE=35, MIN_EMP=20, MAX_EMP=5000;
const TARGET_INDUSTRIES=['software','saas','fintech','financial technology','artificial intelligence','information technology','internet','data'];
const TARGET_COUNTRIES=['united states','canada','united kingdom','germany','australia','netherlands'];
const GOOD_TECH=['hubspot','salesforce','segment','snowflake','stripe','intercom'];
const GOOD_FUNDING=['seed','series a','series b','series c','series d'];
// -----------------------------------
const b=($json.body&&typeof $json.body==='object')?$json.body:$json;
if(!b.company_domain) throw new Error('Clay callback missing company_domain');
const emp=parseInt(b.employee_count,10);
let s=0;
if(Number.isFinite(emp)){ s+= (emp>=MIN_EMP&&emp<=MAX_EMP)?40:(emp>=10&&emp<=20000?20:0);} else s+=10;
const ind=String(b.industry||'').toLowerCase();
s+= ind? (TARGET_INDUSTRIES.some(k=>ind.includes(k))?30:0):5;
const ctry=String(b.country||'').toLowerCase();
s+= TARGET_COUNTRIES.includes(ctry)?15:0;
const tech=(Array.isArray(b.tech_stack)?b.tech_stack:String(b.tech_stack||'').split(',')).map(x=>String(x).toLowerCase());
if(GOOD_TECH.some(t=>tech.some(x=>x.includes(t)))) s+=8;
if(GOOD_FUNDING.includes(String(b.funding_stage||'').toLowerCase())) s+=7;
const enrichment={company_name:b.company_name??null,employee_count:Number.isFinite(emp)?emp:null,industry:b.industry??null,country:b.country??null,annual_revenue:b.annual_revenue??null,funding_stage:b.funding_stage??null,tech_stack:tech.slice(0,25),linkedin_url:b.linkedin_url??null,hiring_signals:b.hiring_signals??null,funding_signals:b.funding_signals??null};
return {json:{
 company_domain:String(b.company_domain).toLowerCase(), visitor_anonymous_id:b.visitor_anonymous_id||null,
 source:b.source||'inbound_web', signals:b.signals||{}, cache_hit:false,
 execution_id:String(b.execution_id||$execution.id), workflow_id:String(b.workflow_id||$workflow.id), t_start:Number(b.t_start)||Date.now(), clay_sent_at:Number(b.clay_sent_at)||null, callback_received_at:Date.now(),
 enrichment, prefilter_score:s, llm_eligible:s>=MIN_PRESCORE,
 llm_called:false, llm_valid:false, llm_error:null, input_tokens:0, output_tokens:0, est_cost_usd:0
}};

const MODEL = 'nvidia/nemotron-3.5-lightning-30b-a3b';
const lead = $json;
const SYSTEM = 'You are a GTM scoring engine. Output ONLY one minified JSON object and nothing else: no markdown, no backticks, no commentary. Schema: {"icp_fit_score":integer 0-100,"intent_strength_score":integer 0-100,"calculated_churn_risk_level":"low"|"medium"|"high"|"critical"}. icp_fit_score = how well the company matches the ideal customer profile (B2B SaaS/AI/fintech, 20-5000 employees, North America/Europe, modern GTM stack). intent_strength_score = how strong the current buying signal is, judged separately from ICP fit, using the signals provided. calculated_churn_risk_level = churn risk for an existing or trialing account based on usage signals (wau_drop_pct, days_since_last_login, seat_utilization_pct); use "low" when no usage signals are present. Use only the data provided. If data is missing, score conservatively.';
const payload = JSON.stringify({
  company_domain: lead.company_domain,
  source: lead.source,
  signals: lead.signals,
  enrichment: lead.enrichment,
  prefilter_score: lead.prefilter_score
}).slice(0, 6000);

const nvidia_request = {
  model: MODEL,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: payload }
  ],
  temperature: 0.1,
  top_p: 0.95,
  max_tokens: 500,
  stream: false,
  chat_template_kwargs: { enable_thinking: false }
};

return {
  json: {
    lead,
    nvidia_request,
    claude_request: nvidia_request
  }
};

const PRICE_IN_PER_MTOK = 0.30, PRICE_OUT_PER_MTOK = 0.60; // NVIDIA Nemotron pricing
let lead;
try { lead = $('Build Claude Request').item.json.lead; } catch(e) { lead = $('Build Claude Request').all()[$itemIndex].json.lead; }
const res = $json;

let text = '';
if (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) {
  text = res.choices[0].message.content;
} else if (Array.isArray(res.content)) {
  text = res.content.filter(x => x.type === 'text').map(x => x.text).join('');
} else if (typeof res === 'string') {
  text = res;
}
text = text.trim();

let p = null, err = null;
try {
  const a = text.indexOf('{'), z = text.lastIndexOf('}');
  if (a === -1 || z <= a) throw new Error('no_json_block');
  p = JSON.parse(text.slice(a, z + 1));
} catch(e) {
  err = 'invalid_json_from_llm';
}

const LV = ['low', 'medium', 'high', 'critical'];
let valid = false;
if (p && Number.isInteger(p.icp_fit_score) && p.icp_fit_score >= 0 && p.icp_fit_score <= 100 &&
    Number.isInteger(p.intent_strength_score) && p.intent_strength_score >= 0 && p.intent_strength_score <= 100 &&
    LV.includes(p.calculated_churn_risk_level)) {
  valid = true;
} else if (!err) {
  err = 'schema_validation_failed';
}

const u = res.usage || {};
const inT = u.prompt_tokens || u.input_tokens || 0;
const outT = u.completion_tokens || u.output_tokens || 0;

return {
  json: {
    ...lead,
    llm_called: true,
    llm_valid: valid,
    llm_error: valid ? null : err,
    llm_model: res.model || 'nvidia/nemotron-3.5-lightning-30b-a3b',
    icp_fit_score: valid ? p.icp_fit_score : null,
    intent_strength_score: valid ? p.intent_strength_score : null,
    calculated_churn_risk_level: valid ? p.calculated_churn_risk_level : null,
    input_tokens: inT,
    output_tokens: outT,
    est_cost_usd: Number(((inT * PRICE_IN_PER_MTOK + outT * PRICE_OUT_PER_MTOK) / 1e6).toFixed(6))
  }
};

let lead;
try { lead = $('Build Claude Request').item.json.lead; } catch(e) { lead = $('Build Claude Request').all()[$itemIndex].json.lead; }
const msg = ($json.error && ($json.error.message || JSON.stringify($json.error))) || JSON.stringify($json).slice(0, 500);
return {
  json: {
    ...lead,
    llm_called: true,
    llm_valid: false,
    llm_error: 'nvidia_http_error',
    error_node: 'Claude GTM Router',
    error_message: String(msg).slice(0, 1000)
  }
};

const l=$json;
let route,status,outcome;
if(!l.llm_called){route='disqualified';status='disqualified';outcome='skipped_llm_prefilter';}
else if(!l.llm_valid){route='needs_review';status='needs_review';outcome='llm_failed_or_invalid';}
else if(['high','critical'].includes(l.calculated_churn_risk_level)){route='churn_save';status='scored';outcome='scored_churn_risk';}
else if(l.icp_fit_score>=70&&l.intent_strength_score>=60){route='sales_priority';status='scored';outcome='scored_hot';}
else if(l.icp_fit_score<40){route='disqualified';status='disqualified';outcome='scored_low_fit';}
else{route='nurture';status='scored';outcome='scored_nurture';}
const createTask=['sales_priority','churn_save','needs_review'].includes(route);
const now=Date.now(); const total=now-Number(l.t_start||now);
const wait=(l.clay_sent_at&&l.callback_received_at)?Math.max(0,Number(l.callback_received_at)-Number(l.clay_sent_at)):0;
const processing=Math.max(0,total-wait);
return {json:{...l,route,status,outcome,create_crm_task:createTask,latency_ms:processing,processing_ms:processing,enrichment_wait_ms:wait,total_ms:total,
 enrichment_summary:JSON.stringify(l.enrichment||{}).slice(0,2000)}};
